#!/usr/bin/env bun
/**
 * KB Crawler — Nightly Centre Website Sync
 *
 * Fetches structured data from the Code Ninjas services API for each enrolled
 * centre, transforms it into voice-agent-optimized <doc> tags, and writes the
 * result back to each centre's Google Doc via n8n webhooks.
 *
 * Usage:
 *   bun run crawl.ts                          # crawl all centres
 *   bun run crawl.ts --centre east-gwillimbury-on-ca  # single centre
 *   bun run crawl.ts --dry-run                # preview without writing
 *   bun run crawl.ts --verbose                # detailed output
 */

import { parseArgs } from "util";
import { readFileSync } from "fs";
import { createHash } from "crypto";

// ---------------------------------------------------------------------------
// CLI args
// ---------------------------------------------------------------------------
const { values: args } = parseArgs({
  options: {
    centre: { type: "string", short: "c" },
    "dry-run": { type: "boolean", default: false },
    verbose: { type: "boolean", short: "v", default: false },
    help: { type: "boolean", short: "h", default: false },
  },
  strict: true,
});

if (args.help) {
  console.log(`
KB Crawler — Nightly Centre Website Sync

Usage:
  bun run crawl.ts [options]

Options:
  -c, --centre <id>   Crawl a single centre by ID
  --dry-run           Preview output without writing to Google Docs
  -v, --verbose       Detailed output
  -h, --help          Show this help
`);
  process.exit(0);
}

const DRY_RUN = args["dry-run"] ?? false;
const VERBOSE = args.verbose ?? false;

// ---------------------------------------------------------------------------
// Config
// ---------------------------------------------------------------------------
const SERVICES_API = "https://services.codeninjas.com/api/v1/facility/profile/slug";
const N8N_BASE = "http://localhost:5678/webhook";
const RESEND_API_KEY = "re_[REDACTED]";
const RESEND_FROM = "onboarding@resend.dev";
const RESEND_TO = "scott.james@codeninjas.com";
const CHAR_LIMIT = 10_000;

const AUTO_START = "═══ AUTO-GENERATED BY KB CRAWLER ═══";
const AUTO_END = "═══ END AUTO-GENERATED ═══";
const MANUAL_START = "═══ MANUAL NOTES (preserved across nightly crawls) ═══";
const MANUAL_END = "═══ END MANUAL ═══";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------
interface Centre {
  id: string;
  slug: string;
  name: string;
  docId: string;
  note?: string;
}

interface CrawlResult {
  centre: string;
  status: "updated" | "unchanged" | "skipped" | "error";
  autoSize: number;
  manualSize: number;
  message: string;
}

interface DocTag {
  id: number;
  title: string;
  category: string;
  content: string;
  tier: number;
}

// ---------------------------------------------------------------------------
// HTML stripping
// ---------------------------------------------------------------------------
function stripHTML(html: string): string {
  if (!html) return "";
  return html
    .replace(/<br\s*\/?>/gi, "\n")
    .replace(/<\/p>/gi, "\n")
    .replace(/<[^>]+>/g, "")
    .replace(/&nbsp;/g, " ")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\n{3,}/g, "\n\n")
    .replace(/[ \t]+/g, " ")
    .split("\n")
    .map((l) => l.trim())
    .filter((l) => l.length > 0)
    .join("\n")
    .trim();
}

// ---------------------------------------------------------------------------
// Fetch centre data from services API
// ---------------------------------------------------------------------------
async function fetchCentreAPI(slug: string): Promise<any> {
  const url = `${SERVICES_API}/${slug}`;
  const res = await fetch(url, { signal: AbortSignal.timeout(15_000) });
  if (!res.ok) throw new Error(`API ${res.status} for ${slug}`);
  return res.json();
}

// ---------------------------------------------------------------------------
// Transform API data → doc tags
// ---------------------------------------------------------------------------
function transformToDocTags(data: any): DocTag[] {
  const tags: DocTag[] = [];
  let id = 1;

  // Parse additionalSettings (JSON string inside JSON)
  let addl: any = {};
  try {
    addl = typeof data.additionalSettings === "string"
      ? JSON.parse(data.additionalSettings)
      : data.additionalSettings || {};
  } catch {
    // If parsing fails, continue with empty additionalSettings
  }

  // --- Tier 1: Hours, Contact, Programs ---

  // Store Hours
  const hoursLines: string[] = [];
  if (data.studentHours) hoursLines.push(`Student Hours: ${data.studentHours}`);
  if (data.officeHours) hoursLines.push(`Office Hours: ${data.officeHours}`);
  if (hoursLines.length > 0) {
    tags.push({
      id: id++,
      title: "Store Hours",
      category: "Hours",
      content: hoursLines.join("\n"),
      tier: 1,
    });
  }

  // Contact Info
  const contactLines: string[] = [];
  if (data.phone) contactLines.push(`Phone: ${data.phone}`);
  if (data.emailAddress) contactLines.push(`Email: ${data.emailAddress}`);
  const addrParts = [data.streetAddress1, data.streetAddress2, data.city, `${data.stateAbbreviation} ${data.postalCode}`].filter(Boolean);
  if (addrParts.length > 0) contactLines.push(`Address: ${addrParts.join(", ")}`);
  if (contactLines.length > 0) {
    tags.push({
      id: id++,
      title: "Contact Info",
      category: "Contact",
      content: contactLines.join("\n"),
      tier: 1,
    });
  }

  // Programs Available
  const programs: string[] = [];
  programs.push(`CREATE (ages 8-14): ${data.isEnrolling ? "Available" : "Not Available"}`);
  if (data.isJrEnabled) programs.push("JR (ages 5-7): Available");
  if (data.isAcademiesEnabled) programs.push("Academies: Available");
  const campsEnabled = addl?.programs?.camps?.isCAMPSEnabled;
  if (campsEnabled) programs.push("Camps: Available");
  if (data.isAfterSchoolEnabled) programs.push("After-School Programs: Available");
  if (data.isBirthdayPartiesEnabled) programs.push("Birthday Parties: Available");
  if (addl?.programs?.isParentnightoutEnabled) programs.push("Parent's Night Out: Available");
  if (addl?.programs?.isClubsEnabled) programs.push("Clubs: Available");
  if (addl?.programs?.isHomeSchoolingEnabled) programs.push("Home Schooling: Available");
  tags.push({
    id: id++,
    title: "Programs Available",
    category: "Programs",
    content: programs.join("\n"),
    tier: 1,
  });

  // --- Tier 2: Camp Pricing, Schedule, Extended Care ---

  const campsInfo = addl?.programs?.camps?.additionalCampsInfo;
  if (campsInfo) {
    const tuition = stripHTML(campsInfo.tution || "");
    if (tuition) {
      tags.push({
        id: id++,
        title: "Camp Pricing",
        category: "Pricing",
        content: tuition,
        tier: 2,
      });
    }

    const campTimes = stripHTML(campsInfo.campTimes || "");
    if (campTimes) {
      tags.push({
        id: id++,
        title: "Camp Schedule",
        category: "Schedule",
        content: campTimes,
        tier: 2,
      });
    }

    const extHours = stripHTML(campsInfo.extendedHours || "");
    if (extHours) {
      tags.push({
        id: id++,
        title: "Extended Care (Before/After Camp)",
        category: "Pricing",
        content: extHours,
        tier: 2,
      });
    }
  }

  // --- Tier 3: Upcoming Events (next 30 days only) ---

  const events = addl?.customPage?.events || [];
  const now = new Date();
  const thirtyDaysOut = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);

  const futureEvents = events
    .filter((e: any) => {
      const d = new Date(e.dateAndTime);
      return d >= now && d <= thirtyDaysOut;
    })
    .sort((a: any, b: any) => new Date(a.dateAndTime).getTime() - new Date(b.dateAndTime).getTime());

  if (futureEvents.length > 0) {
    const eventLines = futureEvents.map((e: any) => {
      const date = new Date(e.dateAndTime).toLocaleDateString("en-US", {
        weekday: "long",
        month: "long",
        day: "numeric",
        year: "numeric",
      });
      const title = (e.content || "").trim();
      const desc = stripHTML(e.desc || "");
      let line = `${date}: ${title}`;
      if (desc) line += `\n  ${desc.split("\n")[0]}`;
      return line;
    });
    tags.push({
      id: id++,
      title: "Upcoming Events",
      category: "Events",
      content: eventLines.join("\n"),
      tier: 3,
    });
  }

  // --- Tier 4: Program Descriptions ---

  const addlPrograms = addl?.programs?.additionalPrograms;
  if (addlPrograms) {
    const descLines: string[] = [];
    if (addlPrograms.afterSchoolPrograms?.description) {
      const desc = addlPrograms.afterSchoolPrograms.description.trim();
      if (desc) descLines.push(`After-School Programs: ${desc}`);
    }
    if (addlPrograms.parentNightOut?.description) {
      const desc = addlPrograms.parentNightOut.description.trim();
      if (desc) descLines.push(`Parent's Night Out: ${desc}`);
    }
    if (addlPrograms.birthdayParty?.description) {
      const desc = addlPrograms.birthdayParty.description.trim();
      if (desc) descLines.push(`Birthday Parties: ${desc}`);
    }
    if (addlPrograms.clubs?.description) {
      const desc = addlPrograms.clubs.description.trim();
      if (desc) descLines.push(`Clubs: ${desc}`);
    }
    if (addlPrograms.homeSchooling?.description) {
      const desc = addlPrograms.homeSchooling.description.trim();
      if (desc) descLines.push(`Home Schooling: ${desc}`);
    }
    if (descLines.length > 0) {
      tags.push({
        id: id++,
        title: "Program Descriptions",
        category: "Programs",
        content: descLines.join("\n\n"),
        tier: 4,
      });
    }
  }

  // --- Tier 5: Social Media ---
  const social = addl?.customPage?.socialMedia;
  if (social) {
    const socialLines: string[] = [];
    if (social.instagramURL) socialLines.push(`Instagram: ${social.instagramURL}`);
    if (social.facebookURL) socialLines.push(`Facebook: ${social.facebookURL}`);
    if (socialLines.length > 0) {
      tags.push({
        id: id++,
        title: "Social Media",
        category: "Social",
        content: socialLines.join("\n"),
        tier: 5,
      });
    }
  }

  return tags;
}

// ---------------------------------------------------------------------------
// Render doc tags to string
// ---------------------------------------------------------------------------
function renderDocTags(tags: DocTag[]): string {
  return tags
    .map((t) => `<doc id=${t.id} title="${t.title}" category="${t.category}">\n${t.content}\n</doc>`)
    .join("\n\n");
}

// ---------------------------------------------------------------------------
// Enforce character limit by removing lowest-tier tags first
// ---------------------------------------------------------------------------
function enforceCharLimit(tags: DocTag[], limit: number): DocTag[] {
  let result = [...tags];
  let rendered = renderDocTags(result);

  // Remove from highest tier number (lowest priority) first
  const maxTier = Math.max(...result.map((t) => t.tier));
  for (let tier = maxTier; tier >= 1 && rendered.length > limit; tier--) {
    result = result.filter((t) => t.tier !== tier);
    rendered = renderDocTags(result);
  }

  return result;
}

// ---------------------------------------------------------------------------
// Google Doc read/write via n8n webhooks
// ---------------------------------------------------------------------------
async function readGoogleDoc(docId: string): Promise<string> {
  const res = await fetch(`${N8N_BASE}/gdocs-read`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ doc_id: docId }),
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok) throw new Error(`gdocs-read returned ${res.status}`);
  const data = await res.json() as any;
  return data.content || "";
}

async function writeGoogleDoc(docId: string, content: string): Promise<void> {
  const res = await fetch(`${N8N_BASE}/gdocs-write`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ doc_id: docId, content, mode: "replace" }),
    signal: AbortSignal.timeout(15_000),
  });
  if (!res.ok) throw new Error(`gdocs-write returned ${res.status}`);
}

// ---------------------------------------------------------------------------
// Extract manual section from existing doc content
// ---------------------------------------------------------------------------
function extractManualSection(content: string): string {
  const startIdx = content.indexOf(MANUAL_START);
  const endIdx = content.indexOf(MANUAL_END);

  if (startIdx !== -1 && endIdx !== -1) {
    return content.substring(startIdx + MANUAL_START.length, endIdx).trim();
  }

  // First run: if no markers exist and there's existing content,
  // treat the whole thing as manual content (migration)
  const autoIdx = content.indexOf(AUTO_START);
  if (autoIdx === -1 && content.trim().length > 0) {
    return content.trim();
  }

  return "";
}

// ---------------------------------------------------------------------------
// Compose full document
// ---------------------------------------------------------------------------
function composeDocument(
  centreName: string,
  autoContent: string,
  manualContent: string,
  hash: string,
): string {
  const now = new Date().toLocaleString("en-US", {
    timeZone: "America/Toronto",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  });

  let doc = `${AUTO_START}
Last updated: ${now} ET
Content hash: ${hash}
Centre: ${centreName} | Source: services.codeninjas.com

${autoContent}

${AUTO_END}

${MANUAL_START}

${manualContent || "(No manual notes yet — staff can add content here)"}

${MANUAL_END}`;

  return doc;
}

// ---------------------------------------------------------------------------
// Content hash (for change detection)
// ---------------------------------------------------------------------------
function contentHash(content: string): string {
  return createHash("sha256").update(content).digest("hex").substring(0, 8);
}

function extractPreviousHash(docContent: string): string {
  const match = docContent.match(/Content hash:\s*([a-f0-9]+)/);
  return match ? match[1] : "";
}

// ---------------------------------------------------------------------------
// Send summary email via Resend
// ---------------------------------------------------------------------------
async function sendSummaryEmail(results: CrawlResult[]): Promise<void> {
  const updated = results.filter((r) => r.status === "updated").length;
  const unchanged = results.filter((r) => r.status === "unchanged").length;
  const errors = results.filter((r) => r.status === "error").length;
  const skipped = results.filter((r) => r.status === "skipped").length;
  const date = new Date().toISOString().split("T")[0];

  const rows = results
    .map(
      (r) =>
        `<tr>
      <td style="padding:4px 8px;border:1px solid #ddd">${r.centre}</td>
      <td style="padding:4px 8px;border:1px solid #ddd;color:${r.status === "error" ? "red" : r.status === "updated" ? "green" : "#666"}">${r.status.toUpperCase()}</td>
      <td style="padding:4px 8px;border:1px solid #ddd">${r.autoSize > 0 ? `${r.autoSize.toLocaleString()} chars` : "-"}</td>
      <td style="padding:4px 8px;border:1px solid #ddd">${r.manualSize > 0 ? `${r.manualSize.toLocaleString()} chars` : "-"}</td>
      <td style="padding:4px 8px;border:1px solid #ddd">${r.message}</td>
    </tr>`,
    )
    .join("\n");

  const html = `
<h2>Nightly KB Crawl — ${date}</h2>
<p><strong>Updated:</strong> ${updated} | <strong>Unchanged:</strong> ${unchanged} | <strong>Skipped:</strong> ${skipped} | <strong>Errors:</strong> ${errors}</p>
<table style="border-collapse:collapse;font-family:monospace;font-size:13px">
  <tr style="background:#f0f0f0">
    <th style="padding:4px 8px;border:1px solid #ddd">Centre</th>
    <th style="padding:4px 8px;border:1px solid #ddd">Status</th>
    <th style="padding:4px 8px;border:1px solid #ddd">Auto Size</th>
    <th style="padding:4px 8px;border:1px solid #ddd">Manual Size</th>
    <th style="padding:4px 8px;border:1px solid #ddd">Notes</th>
  </tr>
  ${rows}
</table>`;

  const res = await fetch("https://api.resend.com/emails", {
    method: "POST",
    headers: {
      Authorization: `Bearer ${RESEND_API_KEY}`,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      from: RESEND_FROM,
      to: RESEND_TO,
      subject: `KB Crawl — ${date} — ${updated} updated, ${unchanged} unchanged, ${errors} errors`,
      html,
    }),
  });

  if (!res.ok) {
    const body = await res.text();
    console.error(`Resend email failed: ${res.status} ${body}`);
  } else if (VERBOSE) {
    console.log("Summary email sent");
  }
}

// ---------------------------------------------------------------------------
// Process a single centre
// ---------------------------------------------------------------------------
async function processCentre(centre: Centre): Promise<CrawlResult> {
  const result: CrawlResult = {
    centre: centre.name,
    status: "error",
    autoSize: 0,
    manualSize: 0,
    message: "",
  };

  try {
    // Skip centres with no doc ID
    if (!centre.docId) {
      result.status = "skipped";
      result.message = "No Google Doc ID configured";
      return result;
    }

    // Skip shared-doc centres (St. Catharines, Burlington share EG's doc)
    if (centre.note?.includes("crawl skipped")) {
      result.status = "skipped";
      result.message = centre.note;
      return result;
    }

    if (VERBOSE) console.log(`Fetching API for ${centre.name} (${centre.slug})...`);

    // 1. Fetch API data
    const apiData = await fetchCentreAPI(centre.slug);

    // 2. Transform to doc tags
    let tags = transformToDocTags(apiData);

    // 3. Enforce char limit
    tags = enforceCharLimit(tags, CHAR_LIMIT);
    const autoContent = renderDocTags(tags);
    result.autoSize = autoContent.length;

    if (VERBOSE) {
      console.log(`  Generated ${tags.length} doc tags, ${autoContent.length} chars`);
      tags.forEach((t) => console.log(`    Tier ${t.tier}: ${t.title} (${t.content.length} chars)`));
    }

    // 4. Compute hash of new auto content
    const newHash = contentHash(autoContent);

    if (DRY_RUN) {
      console.log(`\n--- ${centre.name} (${centre.id}) ---`);
      console.log(`Auto content: ${autoContent.length} chars, hash: ${newHash}`);
      console.log(autoContent);
      result.status = "unchanged";
      result.message = "Dry run — no write";
      return result;
    }

    // 5. Read current Google Doc
    let existingContent = "";
    try {
      existingContent = await readGoogleDoc(centre.docId);
      if (VERBOSE) console.log(`  Read existing doc: ${existingContent.length} chars`);
    } catch (e: any) {
      if (VERBOSE) console.log(`  Could not read existing doc: ${e.message}`);
    }

    // 6. Check hash — skip if unchanged
    const prevHash = extractPreviousHash(existingContent);
    if (prevHash === newHash) {
      result.status = "unchanged";
      result.message = "Content identical to last crawl";
      if (VERBOSE) console.log(`  Hash match (${newHash}) — skipping write`);
      // Still extract manual size for reporting
      const manual = extractManualSection(existingContent);
      result.manualSize = manual.length;
      return result;
    }

    // 7. Preserve manual section
    const manualContent = extractManualSection(existingContent);
    result.manualSize = manualContent.length;

    if (VERBOSE) console.log(`  Manual section: ${manualContent.length} chars`);

    // 8. Compose and write
    const fullDoc = composeDocument(centre.name, autoContent, manualContent, newHash);
    await writeGoogleDoc(centre.docId, fullDoc);

    result.status = "updated";
    result.message = prevHash ? `Hash ${prevHash} → ${newHash}` : "First crawl";
    if (VERBOSE) console.log(`  Written: ${fullDoc.length} chars total`);

    return result;
  } catch (e: any) {
