  let centres: Centre[] = JSON.parse(centresRaw);

  // Filter to single centre if specified
  if (args.centre) {
    centres = centres.filter((c) => c.id === args.centre);
    if (centres.length === 0) {
      console.error(`Centre "${args.centre}" not found in registry`);
      process.exit(1);
    }
  }

  console.log(`KB Crawler — ${new Date().toISOString()}`);
  console.log(`Centres: ${centres.length}${DRY_RUN ? " (dry run)" : ""}`);
  console.log("");

  // Process centres sequentially (gentle on APIs)
  const results: CrawlResult[] = [];
  for (const centre of centres) {
    const result = await processCentre(centre);
    results.push(result);

    // Brief status line
    const icon = result.status === "updated" ? "+" : result.status === "unchanged" ? "=" : result.status === "skipped" ? "-" : "!";
    console.log(`[${icon}] ${result.centre}: ${result.status} — ${result.message}`);
  }

  // Summary
  console.log("");
  const updated = results.filter((r) => r.status === "updated").length;
  const unchanged = results.filter((r) => r.status === "unchanged").length;
  const errors = results.filter((r) => r.status === "error").length;
  const skipped = results.filter((r) => r.status === "skipped").length;
